ADD MAP FLEMENUM VERSION 1
    DEVICE IS 3270 SIZE IS 24 BY 80
    RECORDS ARE FLEWORK
    .
    LITERAL 'FLEMENU'                      ROW 1  COLUMN 2  INTENSITY BRIGHT.
    LITERAL 'COMPANY CAR FLEET'            ROW 1  COLUMN 32 INTENSITY BRIGHT.
    LITERAL '1  EMPLOYEE CAR INQUIRY'      ROW 6  COLUMN 20.
    LITERAL '2  ASSIGN COMPANY CAR'        ROW 7  COLUMN 20.
    LITERAL '3  BUSINESS MILEAGE CLAIM'    ROW 8  COLUMN 20.
    LITERAL 'X  EXIT'                      ROW 10 COLUMN 20.
    LITERAL 'OPTION ==>'                   ROW 14 COLUMN 20.
    FIELD WK-OPTION                        ROW 14 COLUMN 31 LENGTH 1
        UNPROTECTED UNDERSCORE REQUIRED.
    FIELD WK-MSG                           ROW 22 COLUMN 2  LENGTH 60 PROTECTED.
    LITERAL 'ENTER=SELECT  PF3=EXIT'       ROW 24 COLUMN 2.
